import { asset_retire } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    retireAddition: Boolean
  },
  data() {
    return {
      retireName: "",
      loading: false
    };
  },
  watch: {
    retireAddition: {
      async handler() {},
      immediate: true
    }
  },
  computed: {},
  methods: {
    getcal() {
      this.modal = true;
    },
    formatDate(date) {
      if (!date) return null;
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_retire, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "CREATE_RETIRE_REASON",
            retire_reason: this.retireName
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.asset_retire);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "update");
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
